// ===== CONFIG =====
const TOKEN = 's6yXmBDu8IHtcIJA54MOVUqxVPNUSwht/oAxwGR+HyZ2H6cbrRS+i2BGQzfQRsCk8rUiVuGiYVSFVqsgW5SJXNIZHi736tS59Q/yJMP7TVfCA0Lot7p1NYu8ERe2tvh3ipTN12+bFfCTQ/8U0ShzYAdB04t89/1O/w1cDnyilFU=';
const LIFF_URL = 'https://liff.line.me/2010228940-rjXFOkmc';

const body = $input.first().json.body || $input.first().json;
const events = body.events || [];
if (events.length === 0) return [];

function isBusinessHours() {
  const bkk = new Date(Date.now() + 7 * 3600 * 1000);
  const day = bkk.getUTCDay();
  const t = bkk.getUTCHours() * 60 + bkk.getUTCMinutes();
  return day >= 1 && day <= 6 && t >= 480 && t < 1050;
}

function liffBubble(title, desc, btnLabel) {
  return {
    type: 'flex', altText: title,
    contents: {
      type: 'bubble',
      body: { type: 'box', layout: 'vertical', spacing: 'md', contents: [
        { type: 'text', text: title, weight: 'bold', size: 'lg', wrap: true, color: '#cc0000' },
        { type: 'text', text: desc, size: 'sm', color: '#555555', wrap: true }
      ]},
      footer: { type: 'box', layout: 'vertical', contents: [{
        type: 'button', style: 'primary', color: '#cc0000',
        action: { type: 'uri', label: btnLabel, uri: LIFF_URL }
      }]}
    }
  };
}

function qr(items) {
  return { items: items.map(it => ({ type: 'action', action: { type: 'message', label: it.label, text: it.text } })) };
}

const results = [];

for (const event of events) {
  if (!event.replyToken || event.replyToken === '00000000000000000000000000000000') continue;
  let messages = null;
  let savePhone = '';

  if (event.type === 'follow') {
    messages = [
      { type: 'text', text: 'ป.เปา มอเตอร์เซอร์วิส\nตัวแทนจำหน่ายรถจักรยานยนต์ ฮอนด้า ครบวงจร\n\nสอบถามข้อมูลรถ โปรโมชั่น หรือเงื่อนไขการออกรถได้เลยครับ 😊\n\n📱 หรือกดเมนูด้านล่างเพื่อ\n✅ เลือกรุ่นรถที่สนใจ\n✅ คำนวณค่างวดด้วยตัวเอง\n✅ ส่งข้อมูลให้พนักงานช่วยดูแลต่อได้ทันที\n\n🇲🇲 မြန်မာဝန်ထမ်းများမှ ဝန်ဆောင်မှုပေးပါသည်။\nမော်တော်ဆိုင်ကယ်မော်ဒယ်များကို ရွေးချယ်နိုင်ပြီး လစဉ်အရစ်ကျငွေကို ကိုယ်တိုင်တွက်ချက်နိုင်ပါသည်။\nမေးမြန်းလိုသည်များရှိပါက စာပို့၍ ဆက်သွယ်နိုင်ပါသည်။' },
      liffBubble('🛵 ดูรุ่นรถ & คำนวณค่างวด', 'เลือกรุ่นรถ คำนวณค่างวด ดูราคา ได้ตลอด 24 ชม.', 'เลือกรุ่นรถเลย')
    ];

  } else if (event.type === 'message' && event.message && event.message.type === 'text') {
    const raw = (event.message.text || '').trim();
    const tl = raw.toLowerCase();

    // === ตรวจจับเบอร์โทร (เก็บไว้ผูก userId — เฉพาะลูกค้าที่มีโปรไฟล์อยู่แล้ว) ===
    const _pm = (raw.match(/0[\d\s-]{8,12}/) || [''])[0].replace(/\D/g, '');
    savePhone = (_pm.length >= 9 && _pm.length <= 10) ? _pm : '';

    // === ลูกค้าส่งเบอร์มา → ขอบคุณ + บันทึกเบอร์ ===
    if (savePhone) {
      messages = [{ type: 'text', text: 'ขอบคุณที่ให้เราดูแล 🙏 เจ้าหน้าที่จะติดต่อกลับโดยเร็วที่สุด หากมีข้อสงสัยเพิ่มเติม สามารถแจ้งได้เลยครับ' }];

    // === บริการพิเศษ (ทำงาน 24 ชม.) ===
    // ทดลองขับ: เลือกรุ่นแล้ว → ถามวัน
    } else if (raw.includes('อยากทดลองขับ')) {
      messages = [{ type: 'text', text: 'รับทราบครับ 😊 สะดวกมาทดลองขับที่สาขาวังน้อยวันไหน เวลาไหนครับ?\nเช่น เสาร์นี้ บ่าย 2 / อาทิตย์ เช้า\n\nพร้อมเบอร์โทร เดี๋ยวเจ้าหน้าที่ยืนยันนัดและเตรียมรถไว้ให้ครับ 🙏' }];

    // ทดลองขับ: เข้าทาง → เลือกรุ่น
    } else if (raw.includes('สนใจทดลองขับ') || (tl.includes('ทดลองขับ') && !raw.includes('อยากทดลองขับ'))) {
      messages = [{
        type: 'text',
        text: '🏍️ ทดลองขับฟรีที่สาขาวังน้อยครับ มีให้ลอง 2 รุ่น เลือกได้เลยครับ',
        quickReply: qr([
          { label: 'PCX160 Roadsync', text: 'อยากทดลองขับ PCX160 Roadsync' },
          { label: 'UC3 ไฟฟ้า', text: 'อยากทดลองขับ UC3 ไฟฟ้า' }
        ])
      }];

    // เทิร์นรถเก่า
    } else if (raw.includes('สนใจเทิร์นรถเก่า') || tl.includes('เทิร์น')) {
      messages = [{ type: 'text', text: 'สนใจเทิร์นรถเก่าใช่ไหมครับ 🔄 รับเทิร์นทุกรุ่นเลยครับ\n\nรบกวนพิมพ์ รุ่นรถเก่า + ปี ที่จะเทิร์น (เช่น Wave110 ปี 2563) พร้อมเบอร์โทรครับ\n\nการตีราคาต้องดูสภาพรถจริงที่ร้าน เดี๋ยวเจ้าหน้าที่โทรนัดวันเอารถมาประเมินให้ครับ 🙏' }];

    // === Guided lead flow (ทำงาน 24 ชม.) ===
    } else if (raw.includes('พร้อมให้โทรได้เลย')) {
      messages = [{ type: 'text', text: 'รับทราบครับ เดี๋ยวเจ้าหน้าที่โทรกลับหาเลยครับ 📞\nขอบคุณที่ไว้วางใจ ป.เปา มอเตอร์เซอร์วิสครับ 🙏\n\n(ถ้ายังไม่ได้ฝากเบอร์ รบกวนพิมพ์เบอร์โทรไว้ได้เลยครับ)' }];

    } else if (raw.includes('ขอนัดเวลาให้โทร')) {
      messages = [{ type: 'text', text: 'ได้เลยครับ 🙏 สะดวกให้โทรช่วงไหน พิมพ์บอกได้เลยครับ\nเช่น บ่าย 2 / หลังเลิกงาน / พรุ่งนี้เช้า\n\n(พร้อมเบอร์โทร ถ้ายังไม่ได้ฝากไว้ครับ)' }];

    } else if (raw.includes('ขอสอบถามทางแชทก่อน')) {
      messages = [{ type: 'text', text: 'ได้เลยครับ 😊 สอบถามเข้ามาได้เลย เดี๋ยวเจ้าหน้าที่มาตอบให้ครับ' }];

    } else if (raw.includes('สะดวกทำสัญญา')) {
      messages = [{
        type: 'text',
        text: 'รับทราบครับ 🙏 เรื่องจัดไฟแนนซ์ไม่ต้องกังวลนะครับ ร้านมีหลายบริษัทให้เลือก และมีทีมช่วยดูเงื่อนไขให้ผ่านง่ายที่สุดครับ\n\nขอเจ้าหน้าที่โทรอธิบายเงื่อนไขให้ชัดๆ สะดวกแบบไหนดีครับ?',
        quickReply: qr([
          { label: '📞 โทรได้เลย', text: 'พร้อมให้โทรได้เลย' },
          { label: '⏰ นัดเวลาโทร', text: 'ขอนัดเวลาให้โทร' },
          { label: '💬 ขอแชทก่อน', text: 'ขอสอบถามทางแชทก่อน' }
        ])
      }];

    } else if (tl.includes('สาขา') || tl === 'สาขาของเรา') {
      messages = [{ type: 'text', text: '📍 สาขาวังน้อย\n☎️ 092-2499686\n🗺️ https://maps.app.goo.gl/9HexF99DPcKtdtsj9\n\n📍 สาขานครหลวง\n☎️ 092-2499685\n🗺️ https://maps.app.goo.gl/z1qu63BnxFthPtdW9' }];

    } else if (tl.includes('เอกสาร') || tl.includes('ออกรถ')) {
      messages = [{ type: 'image', originalContentUrl: 'https://raw.githubusercontent.com/waruton11/porpaor-motorservice/main/images/doc-requirements.png', previewImageUrl: 'https://raw.githubusercontent.com/waruton11/porpaor-motorservice/main/images/doc-requirements.png' }];

    } else if (tl.includes('myanmar') || tl.includes('myanmar support')) {
      messages = [{ type: 'text', text: 'ဆက်သွယ်ရန် ဖုန်းနံပါတ် ပေးပါ ခင်ဗျာ 📞\nMyanmar staff ဆက်သွယ်ပေးပါမည်ခင်ဗျာ\n\nส่งเบอร์โทรมาได้เลยครับ เซลพม่าจะโทรหาโดยเร็วครับ 😊' }];
    }
  }

  if (messages) {
    const userId = (event.source && event.source.userId) ? event.source.userId : '';
    results.push({ json: { replyToken: event.replyToken, messages: messages, token: TOKEN, userId: userId, savePhone: savePhone } });
  }
}

return results;

// เก็บเฉพาะข้อความตัวอักษรที่ลูกค้าพิมพ์เข้ามา — ระบบเก็บคำถามลูกค้าอัตโนมัติ (FAQ)
// ทำงานเป็นสาขาแยกจาก bot reply: ไม่กระทบการตอบแชท และเก็บได้แม้เป็นคำถามที่ bot ไม่รู้จัก
// เซ็นเซอร์เบอร์โทรก่อนบันทึก (PDPA) + escape ' กัน SQL injection จากข้อความลูกค้า
const body = $input.first().json.body || $input.first().json;
const events = body.events || [];
const esc = (s) => String(s).replace(/'/g, "''");
const rows = [];
for (const event of events) {
  if (event.type !== 'message' || !event.message || event.message.type !== 'text') continue;
  let text = (event.message.text || '').trim();
  if (!text) continue;
  // เซ็นเซอร์เบอร์โทร: ลำดับเลขที่ล้างแล้วยาว 9–10 หลัก (โทรศัพท์ไทย) → [เบอร์โทร]
  text = text.replace(/0[\d\s-]{8,12}/g, (m) => {
    const d = m.replace(/\D/g, '');
    return (d.length >= 9 && d.length <= 10) ? '[เบอร์โทร]' : m;
  });
  const userId = (event.source && event.source.userId) ? event.source.userId : '';
  rows.push({ json: {
    sql: "INSERT INTO messages (line_user_id, brand, message_type, text) VALUES ('"
      + esc(userId) + "', 'honda', 'text', '" + esc(text) + "');"
  }});
}
return rows;
